from audio_helpers import *
from bie.qa.audio_v2.pcm import read_pcm

class EvaluationTests(FixtureCase):
    def test_positive_fixture_is_only_bounded_checks(self):self.assertEqual(self.check().status,'CHECKS_PASSED');self.assertFalse(self.check().product_accepted)
    def test_unsigned_review_required(self):self.assertEqual(evaluate(self.r,self.root,self.p,as_of=NOW).status,'REVIEW_REQUIRED')
    def test_report_recomputed_exactly(self):self.assertEqual(verify_reports(self.check(),self.r,self.root,self.p,as_of=NOW,**options(self.r,self.p)),self.check())
    def test_report_tamper_rejected(self):
        a=self.check();a=replace(a,sync=replace(a.sync,measurements=(('decoded_clips',77),)))
        with self.assertRaises(ContractError):verify_reports(a,self.r,self.root,self.p,as_of=NOW,**options(self.r,self.p))
    def test_actual_audio_modified(self):(self.root/self.r.clips[0].wav.path).write_bytes(b'bad');self.assertEqual(self.check().status,'BLOCKED')
    def test_source_modified(self):(self.root/self.r.source.sources[0].artifact.path).write_bytes(b'bad');self.assertEqual(self.check().status,'BLOCKED')
    def test_late_audio(self):self.assertCode(self.check(replace(self.r,clips=(replace(self.r.clips[0],start_ms=100),))),'AUDIO_PLACEMENT')
    def test_overflow(self):self.assertCode(self.check(p=replace(self.p,narrations=(replace(self.p.narrations[0],end_ms=500),))),'AUDIO_SLOT_OVERFLOW')
    def test_wrong_sample_rate(self):self.assertCode(self.check(p=replace(self.p,narrations=(replace(self.p.narrations[0],sample_rate=16000),))),'AUDIO_SAMPLE_RATE')
    def test_wrong_language(self):self.assertCode(self.check(replace(self.r,clips=(replace(self.r.clips[0],language='hi'),))),'AUDIO_VOICE_OR_LANGUAGE')
    def test_wrong_voice(self):self.assertCode(self.check(replace(self.r,clips=(replace(self.r.clips[0],voice_id='other'),))),'AUDIO_VOICE_OR_LANGUAGE')
    def test_lesson_scope(self):self.assertCode(self.check(replace(self.r,lesson_id='other')),'AUDIO_LESSON_SCOPE')
    def test_claim_omission(self):self.assertCode(self.check(p=replace(self.p,narrations=(replace(self.p.narrations[0],claim_ids=('missing',)),))),'AUDIO_CLAIM_COVERAGE')
    def test_timing_stale_hash(self):self.assertCode(self.check(self.timing(audio_sha256='0'*64)),'AUDIO_TIMING_BINDING')
    def test_timing_stale_transcript(self):self.assertCode(self.check(self.timing(transcript_sha256='0'*64)),'AUDIO_TIMING_BINDING')
    def test_timing_wrong_count(self):self.assertCode(self.check(self.timing(samples=9000)),'AUDIO_TIMING_BINDING')
    def test_timing_wrong_clip(self):self.assertCode(self.check(self.timing(clip_id='other')),'AUDIO_TIMING_BINDING')
    def test_word_coverage(self):self.assertCode(self.check(self.timing(words=(Word(0,0,5,'Force',0,2000),))),'AUDIO_WORD_COVERAGE')
    def test_word_wrong_text(self):self.assertCode(self.check(self.timing(words=(Word(0,0,5,'Wrong',0,2000),Word(1,6,11,'moves',2000,4000),Word(2,12,20,'objects.',4000,8000)))),'AUDIO_WORD_TEXT_MISMATCH')
    def test_engine_times_not_phonetics(self):self.assertCode(self.check(self.timing(basis='engine_events')),'AUDIO_ACOUSTIC_ALIGNMENT_UNPROVEN')
    def test_reported_times_not_measured(self):self.assertEqual(self.check(self.timing(basis='reported')).status,'REVIEW_REQUIRED')
    def test_synthetic_times_not_measured(self):self.assertEqual(self.check(self.timing(basis='synthetic')).status,'REVIEW_REQUIRED')
    def test_cue_missing_word(self):self.assertCode(self.check(p=replace(self.p,cues=(replace(self.p.cues[0],word_index=10),))),'AUDIO_CUE_WORD_MISSING')
    def test_cue_offset(self):self.assertCode(self.check(p=replace(self.p,cues=(replace(self.p.cues[0],start_ms=100,end_ms=350),))),'AUDIO_CUE_MISALIGNMENT')
    def test_cue_tolerance_boundary(self):self.assertNotIn('AUDIO_CUE_MISALIGNMENT',codes(self.check(p=replace(self.p,cues=(replace(self.p.cues[0],start_ms=10,end_ms=260),)))))
    def test_caption_missing(self):self.assertCode(self.check(replace(self.r,captions=())),'AUDIO_CAPTION_TRACK_INVENTORY')
    def test_caption_wrong_words(self):self.assertCode(self.check(self.captions('1\n00:00:00,000 --> 00:00:01,000\nForce stops objects.\n')),'AUDIO_CAPTION_TEXT_MISMATCH')
    def test_caption_missing_word(self):self.assertCode(self.check(self.captions('1\n00:00:00,000 --> 00:00:00,500\nForce moves\n')),'AUDIO_CAPTION_COVERAGE')
    def test_caption_late(self):self.assertCode(self.check(self.captions('1\n00:00:00,200 --> 00:00:01,200\nForce moves objects.\n')),'AUDIO_CAPTION_SYNC')
    def test_caption_fast(self):self.assertCode(self.check(self.captions('1\n00:00:00,000 --> 00:00:00,100\nForce moves objects.\n')),'AUDIO_CAPTION_READING_RATE')
    def test_caption_duration(self):self.assertCode(self.check(self.captions('1\n00:00:00,000 --> 00:00:00,100\nForce moves objects.\n')),'AUDIO_CAPTION_DURATION')
    def test_caption_lines(self):self.assertCode(self.check(self.captions('1\n00:00:00,000 --> 00:00:01,000\nForce\nmoves\nobjects.\n')),'AUDIO_CAPTION_LINE_LIMIT')
    def test_caption_language(self):self.assertCode(self.check(replace(self.r,captions=(replace(self.r.captions[0],language='hi'),))),'AUDIO_CAPTION_LANGUAGE')
    def test_webvtt_supported(self):self.assertEqual(self.check(self.captions('WEBVTT\n\n00:00:00.000 --> 00:00:01.000\nForce moves objects.\n','webvtt')).status,'CHECKS_PASSED')
    def test_caption_overlap(self):self.assertCode(self.check(self.captions('1\n00:00:00,000 --> 00:00:00,400\nForce\n\n2\n00:00:00,250 --> 00:00:01,000\nmoves objects.\n')),'AUDIO_CAPTION_OVERLAP')
    def test_pronunciation_missing(self):self.assertCode(self.check(replace(self.r,pronunciation=())),'AUDIO_PRONUNCIATION_EVIDENCE_MISSING')
    def test_transcript_not_pronunciation(self):self.assertCode(self.check(self.pronunciation(basis='transcript_only')),'AUDIO_PRONUNCIATION_NOT_ACOUSTIC')
    def test_pronunciation_synthetic(self):self.assertEqual(self.check(self.pronunciation(basis='synthetic')).status,'REVIEW_REQUIRED')
    def test_pronunciation_stale_audio(self):self.assertCode(self.check(self.pronunciation(audio_sha256='0'*64)),'AUDIO_PRONUNCIATION_BINDING')
    def test_pronunciation_wrong_voice(self):self.assertCode(self.check(self.pronunciation(voice_id='other')),'AUDIO_PRONUNCIATION_BINDING')
    def test_pronunciation_wrong_language(self):self.assertCode(self.check(self.pronunciation(language='hi')),'AUDIO_PRONUNCIATION_BINDING')
    def test_pronunciation_wrong_form(self):self.assertCode(self.check(self.pronunciation(observations=(PronunciationObservation('force',0,2000,'wrong','correct'),))),'AUDIO_PRONUNCIATION_MISMATCH')
    def test_pronunciation_incorrect_verdict(self):self.assertCode(self.check(self.pronunciation(observations=(PronunciationObservation('force',0,2000,'fɔːs','incorrect'),))),'AUDIO_PRONUNCIATION_MISMATCH')
    def test_pronunciation_uncertain(self):self.assertEqual(self.check(self.pronunciation(observations=(PronunciationObservation('force',0,2000,'fɔːs','uncertain'),))).status,'REVIEW_REQUIRED')
    def test_pronunciation_wrong_occurrence(self):self.assertCode(self.check(self.pronunciation(observations=(PronunciationObservation('force',2000,4000,'fɔːs','correct'),))),'AUDIO_TERM_WINDOW')
    def test_pronunciation_extra_term(self):self.assertCode(self.check(self.pronunciation(observations=(PronunciationObservation('other',0,2000,'fɔːs','correct'),))),'AUDIO_TERM_COVERAGE')
    def test_silence_in_audio(self):
        a=artifact(self.root,'silent.wav',wav_bytes(mode='silence'),'silent');self.assertCode(self.check(replace(self.r,clips=(replace(self.r.clips[0],wav=a),))),'AUDIO_SILENT_CLIP')
    def test_clipping_in_audio(self):
        a=artifact(self.root,'clipped.wav',wav_bytes(mode='clipped'),'clipped');self.assertCode(self.check(replace(self.r,clips=(replace(self.r.clips[0],wav=a),))),'AUDIO_CLIPPING')
    def test_zero_word_window(self):
        b=wav_bytes();pcm=read_pcm(b);data=b[:44]+b'\0'*4000+b[4044:];a=artifact(self.root,'part-silent.wav',data,'part-silent')
        r=self.timing(audio_sha256=a.sha256);r=replace(r,clips=(replace(r.clips[0],wav=a),));self.assertCode(self.check(r),'AUDIO_SILENT_WORD_WINDOW')
